@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Nunito:wght@600;700;800;900&display=swap');
:root{--ink:#172b3a;--muted:#75848b;--paper:#f6f7ed;--white:#fff;--green:#62bd75;--green-dark:#348b56;--mint:#e4f5e5;--yellow:#f6c95f;--orange:#f29a56;--red:#e66a67;--purple:#8e72cd;--line:#e6e9df;--shadow:0 12px 30px #21334412}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(#dbe7d4 1px,transparent 1px);background-size:22px 22px}.app-shell{max-width:1180px;padding:0 28px;margin:auto}.topbar{height:88px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e5e9dd}.brand{border:0;background:none;color:var(--ink);display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;padding:0}.brand-icon{width:43px;height:43px;background:#dff3e1;border-radius:14px;display:grid;place-items:center;font-size:23px}.brand b{font:900 14px 'Nunito';letter-spacing:.8px;display:block}.brand small{font-size:9px;font-weight:800;letter-spacing:1.6px;color:#8b9b8c}.top-stats{display:flex;gap:9px}.stat-chip{border-radius:13px;border:1px solid var(--line);background:#fff;padding:8px 13px;min-width:76px;text-align:center;box-shadow:0 3px 8px #18304408}.stat-chip span{font-size:9px;letter-spacing:1.2px;font-weight:800;color:#8a9899;display:block;margin-bottom:2px}.stat-chip b{font-size:14px}.lives-chip{min-width:108px}.timer-chip{background:#fff2e4;border-color:#f8dfc7}.icon-button{border:1px solid var(--line);background:#fff;border-radius:12px;padding:10px 13px;color:var(--muted);font:700 11px 'DM Sans';cursor:default}.icon-button span{margin-left:4px}main{min-height:calc(100vh - 148px);padding:28px 0 34px}footer{height:52px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:center;gap:8px;color:#8b9691;font-size:11px;font-weight:600}footer span{color:var(--green)}button{font-family:inherit}.home-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:24px;align-items:stretch}.hero-card{background:#fff;border:1px solid var(--line);border-radius:26px;padding:34px 38px;position:relative;overflow:hidden;box-shadow:var(--shadow);min-height:366px}.hero-card:after{content:'';position:absolute;width:270px;height:270px;border-radius:50%;right:-52px;top:-63px;background:#f0f8e9;z-index:0}.hero-copy{position:relative;z-index:1;max-width:580px}.eyebrow{display:inline-flex;align-items:center;gap:7px;background:#e8f6e8;color:#438d57;border-radius:99px;padding:7px 11px;font-size:10px;font-weight:900;letter-spacing:1.3px}.hero-card h1{font:900 clamp(32px,4.2vw,52px)/1.04 'Nunito';letter-spacing:-1.9px;margin:17px 0 12px;max-width:530px}.hero-card h1 em{font-style:normal;color:var(--green-dark)}.hero-card p{color:#73838a;line-height:1.65;font-size:14px;max-width:470px;margin:0 0 22px}.hero-actions{display:flex;gap:10px;flex-wrap:wrap}.primary,.secondary,.next-button{border:0;border-radius:13px;padding:13px 19px;font-weight:900;font-size:13px;cursor:pointer;transition:transform .15s,filter .15s}.primary:hover,.secondary:hover,.next-button:hover{transform:translateY(-2px);filter:brightness(.98)}.primary{background:#348b56;color:white;box-shadow:0 6px 14px #348b5630}.secondary{background:#fff;border:1px solid var(--line);color:var(--ink)}.hero-art{position:absolute;right:28px;bottom:15px;z-index:1;font-size:95px;filter:drop-shadow(0 11px 8px #172b3a12);transform:rotate(5deg)}.hero-art .bubble{position:absolute;font-size:25px;animation:float 3s ease-in-out infinite}.hero-art .b1{left:-24px;top:8px}.hero-art .b2{right:-2px;top:-16px;animation-delay:.7s}.hero-art .b3{left:16px;bottom:3px;animation-delay:1.3s}@keyframes float{50%{transform:translateY(-9px)}}.side-stack{display:grid;gap:14px}.mini-card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:21px 23px;box-shadow:var(--shadow)}.mini-head{display:flex;align-items:center;gap:12px}.mini-icon{height:43px;width:43px;border-radius:14px;background:#fff2dc;display:grid;place-items:center;font-size:21px}.mini-head h3{margin:0;font:900 16px 'Nunito'}.mini-head small{color:#8b9899;font-size:10px;font-weight:700}.mini-card p{font-size:12px;color:#77868b;line-height:1.55;margin:13px 0 0}.practice-card{background:#eef8e9;display:flex;align-items:center;justify-content:space-between;gap:10px;border-color:#dbeed7}.practice-card h3{font:900 16px 'Nunito';margin:0 0 5px}.practice-card p{margin:0;max-width:230px}.practice-launch{border:0;background:#fff;border-radius:13px;padding:12px 15px;color:#348b56;font-weight:900;white-space:nowrap;cursor:pointer;box-shadow:0 4px 12px #163c2012}.map-section{margin-top:24px;background:#fff;border:1px solid var(--line);border-radius:24px;padding:22px 25px;box-shadow:var(--shadow)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:17px}.section-head h2{font:900 21px 'Nunito';margin:0}.section-head p{margin:4px 0 0;color:#829093;font-size:11px}.map-legend{display:flex;gap:10px;flex-wrap:wrap;color:#78868a;font-size:9px;font-weight:800}.legend-dot{display:inline-flex;align-items:center;gap:5px}.legend-dot:before{content:'';width:8px;height:8px;border-radius:50%;background:var(--c)}.stage-map{display:grid;grid-template-columns:repeat(10,1fr);gap:10px}.stage-node{border:1px solid #e5e9e3;background:#f8faf6;border-radius:15px;min-height:70px;display:flex;align-items:center;justify-content:center;flex-direction:column;position:relative;color:#9da7a1;cursor:pointer;transition:.18s}.stage-node.unlocked{background:#fff;border-color:#d8e8d8;color:var(--ink);cursor:pointer}.stage-node.unlocked:hover{transform:translateY(-3px);box-shadow:0 7px 13px #122b2412}.stage-node.done{background:#e8f6e8;border-color:#bde2bf}.stage-node .node-num{font:900 15px 'Nunito'}.stage-node .node-icon{font-size:11px;margin-top:3px}.stage-node .node-lock{font-size:10px}.difficulty{font-size:9px;font-weight:900;letter-spacing:1.2px;display:flex;align-items:center;gap:7px;margin:0 0 12px}.difficulty span{width:8px;height:8px;border-radius:50%;background:currentColor}.stage-screen{max-width:850px;margin:0 auto}.stage-progress{height:8px;background:#e7ebe3;border-radius:99px;overflow:hidden;margin:11px 0 21px}.stage-progress span{display:block;height:100%;border-radius:99px;background:var(--green);transition:width .4s}.question-card{background:#fff;border:1px solid var(--line);border-radius:24px;padding:30px 34px;box-shadow:var(--shadow);position:relative}.question-card h1{font:900 clamp(24px,3vw,34px)/1.2 'Nunito';margin:7px 0 8px}.question-card .subtitle{color:#77858a;font-size:14px;line-height:1.55;margin:0 0 21px}.question-emoji{position:absolute;right:30px;top:25px;font-size:36px;background:#f3f8ec;width:60px;height:60px;display:grid;place-items:center;border-radius:18px}.options{display:grid;grid-template-columns:1fr 1fr;gap:11px}.option{min-height:60px;border:1px solid #e3e9e0;background:#fbfcf9;border-radius:15px;text-align:left;padding:13px 16px;font-weight:800;color:#304454;cursor:pointer;transition:.15s;display:flex;align-items:center;gap:11px}.option:hover:not(:disabled){border-color:#85c792;background:#f3fbf2;transform:translateY(-1px)}.option .option-letter{width:27px;height:27px;flex:none;border-radius:9px;background:#edf2eb;display:grid;place-items:center;color:#83918b;font-size:11px}.option.correct{background:#e8f7e9;border-color:#72c382;color:#287a45}.option.wrong{background:#fff0ee;border-color:#e98a7f;color:#a84037}.option:disabled{cursor:default}.feedback{margin-top:15px;border-radius:14px;padding:13px 15px;line-height:1.5;font-size:13px;display:none}.feedback.show{display:flex;gap:10px;animation:pop .25s ease}.feedback.good{background:#eaf7eb;color:#337a47}.feedback.bad{background:#fff0ed;color:#9d463d}@keyframes pop{from{transform:translateY(5px);opacity:0}to{transform:none;opacity:1}}.feedback strong{display:block;margin-bottom:2px}.question-footer{margin-top:18px;display:flex;align-items:center;justify-content:space-between;gap:12px}.hint-line{font-size:11px;color:#899598}.next-button{background:#172b3a;color:#fff;padding:13px 21px;display:none}.next-button.show{display:inline-flex}.retry-note{color:#b94a42;font-size:11px;font-weight:800}.pill-tag{font-size:10px;font-weight:900;color:#768586;background:#f1f4ef;border-radius:99px;padding:7px 10px}.timer-banner{border:1px solid #f5dfc9;background:#fff6e9;border-radius:13px;padding:9px 13px;margin:0 0 12px;color:#9b6538;font-size:12px;font-weight:800;display:flex;justify-content:space-between}.timer-banner.urgent{background:#fff0ed;color:#ba4037;border-color:#f1c1b9}.soap-screen{max-width:930px;margin:auto}.soap-card{background:white;border:1px solid var(--line);border-radius:25px;padding:27px 30px;box-shadow:var(--shadow)}.soap-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.soap-heading h1{font:900 29px 'Nunito';margin:5px 0}.soap-heading p{color:#78888b;font-size:13px;margin:0;line-height:1.5}.soap-layout{display:grid;grid-template-columns:1.05fr .95fr;gap:23px;margin-top:22px}.lab-visual{min-height:320px;border-radius:20px;background:#f1f7e9;display:grid;place-items:center;position:relative;overflow:hidden;border:1px solid #e1edd8}.lab-visual:before,.lab-visual:after{content:'';position:absolute;border-radius:50%;background:#e4f0d7;width:200px;height:200px;left:-80px;bottom:-105px}.lab-visual:after{left:auto;right:-75px;bottom:-110px;width:210px;height:210px}.beaker-wrap{z-index:1;position:relative;text-align:center}.beaker{width:148px;height:186px;border:5px solid #7295a0;border-top:0;border-radius:4px 4px 30px 30px;background:linear-gradient(transparent 46%,#d1eff0a1 47%);position:relative;overflow:hidden;clip-path:polygon(5% 0,95% 0,84% 100%,16% 100%);filter:drop-shadow(0 10px 5px #44647420)}.liquid{position:absolute;bottom:0;left:0;right:0;height:0%;background:#f4c968;transition:height .8s,background .7s;border-radius:0 0 25px 25px}.liquid:after{content:'';position:absolute;left:0;right:0;top:-7px;height:14px;border-radius:50%;background:#ffffff55}.beaker-label{position:absolute;left:0;right:0;top:50%;font-weight:900;font-size:10px;letter-spacing:1px;color:#63838e;z-index:2}.beaker-caption{font-weight:900;font-size:12px;margin-top:12px;position:relative;z-index:2}.thermometer{position:absolute;left:21%;bottom:18%;font-size:31px;z-index:3;transition:transform .2s}.soap-panel{display:flex;flex-direction:column}.step-count{font-size:10px;letter-spacing:1.3px;font-weight:900;color:#76927b}.step-title{font:900 20px 'Nunito';margin:5px 0 8px}.step-copy{font-size:13px;line-height:1.55;color:#74848a;margin:0 0 15px}.measure-display{font:900 30px 'Nunito';color:#348b56;text-align:center;margin:5px}.measure-sub{text-align:center;color:#8b9897;font-size:10px;font-weight:800;margin-bottom:10px}.range{width:100%;accent-color:#348b56;margin:12px 0 3px}.button-row{display:flex;gap:9px;margin-top:11px}.button-row .primary,.button-row .secondary{flex:1}.safety-note{padding:10px 11px;background:#fff3dd;border:1px solid #f3dfb9;border-radius:12px;color:#946d2d;font-size:11px;font-weight:700;line-height:1.45;margin:0 0 12px}.stir-wrap{border:1px solid #e2e8de;border-radius:18px;padding:14px;background:#fbfcf8;text-align:center;touch-action:none;user-select:none}.stir-instruction{font:900 15px 'Nunito';color:#348b56}.stir-pad{height:180px;width:180px;margin:12px auto 8px;position:relative;border-radius:50%;background:radial-gradient(circle,#fff 48%,#e6f4e3 50%,#d8ecd6 66%,#f7faf4 67%);border:1px dashed #7ebd86;display:grid;place-items:center;cursor:grab;touch-action:none}.stir-pad.dragging{cursor:grabbing}.stir-arrow{position:absolute;font-size:31px;color:#348b56;right:15px;top:14px;animation:rotate 4s linear infinite}@keyframes rotate{to{transform:rotate(360deg)}}.stir-center{font-size:43px}.stir-progress{height:7px;border-radius:99px;background:#e4e9e1;overflow:hidden;margin:11px 0 4px}.stir-progress span{height:100%;width:0;display:block;background:linear-gradient(90deg,#65c379,#2d955a);transition:width .2s}.stir-caption{font-size:10px;color:#889590;font-weight:700}.stir-error{height:17px;color:#d34b44;font-size:11px;font-weight:900;margin-top:4px}.stage-feedback{padding:11px 12px;border-radius:12px;background:#e9f7e9;color:#347a48;font-size:12px;line-height:1.45;margin-top:12px}.stage-feedback.bad{background:#fff0ed;color:#ab453e}.practice-banner{background:#eaf6e7;border-radius:14px;padding:12px 15px;font-size:12px;font-weight:700;color:#477b4c;margin-bottom:16px}.completion-card{max-width:760px;margin:30px auto;background:#fff;border:1px solid var(--line);border-radius:26px;padding:38px;text-align:center;box-shadow:var(--shadow);position:relative;overflow:hidden}.completion-card:before{content:'MISTER AHMED ABDELHADI';position:absolute;top:47%;left:0;right:0;font:900 clamp(25px,6vw,65px) 'Nunito';color:#348b560b;transform:rotate(-13deg);white-space:nowrap;pointer-events:none}.trophy{font-size:76px;animation:float 2.5s ease-in-out infinite}.completion-card h1{font:900 38px 'Nunito';margin:12px 0 8px}.completion-card p{color:#79898b;line-height:1.6;max-width:490px;margin:0 auto 17px}.final-score{display:inline-block;background:#f0f8e9;padding:12px 22px;border-radius:15px;color:#348b56;font-weight:900;font-size:16px}.certificate{border:2px dashed #b6d8b5;padding:17px;border-radius:15px;margin:20px auto;max-width:460px;position:relative;background:#fcfdf9}.certificate strong{font:900 22px 'Nunito';display:block;color:#348b56}.certificate small{font-size:10px;color:#82908b;letter-spacing:1.5px;font-weight:900}.celebrate{font-size:25px;margin:12px}.modal-backdrop{position:fixed;inset:0;background:#12253673;z-index:10;display:grid;place-items:center;padding:20px}.modal{width:min(520px,100%);background:#fff;border-radius:24px;padding:28px;box-shadow:0 20px 70px #11263535;position:relative}.modal h2{font:900 25px 'Nunito';margin:0 0 8px}.modal p,.modal li{font-size:13px;color:#73848a;line-height:1.6}.modal ul{padding-left:20px}.modal-close{position:absolute;right:18px;top:17px;border:0;background:#f1f4ef;border-radius:10px;width:32px;height:32px;font-size:17px;cursor:pointer}.toast{position:fixed;bottom:70px;left:50%;transform:translate(-50%,20px);background:#172b3a;color:#fff;border-radius:12px;padding:11px 16px;font-size:12px;font-weight:800;opacity:0;pointer-events:none;transition:.25s;z-index:20;box-shadow:0 8px 20px #18293830}.toast.show{opacity:1;transform:translate(-50%,0)}.confetti{position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden}.confetti i{position:absolute;top:-20px;width:9px;height:13px;animation:fall 3s linear forwards;left:var(--x);background:var(--color);transform:rotate(var(--rot));border-radius:2px}@keyframes fall{to{transform:translateY(110vh) rotate(760deg);opacity:.2}}.empty-state{text-align:center;color:#87938e;padding:16px}.home-link{font-size:11px;font-weight:800;color:#698078;cursor:pointer;border:0;background:transparent;padding:4px 0}.inline-help{font-size:11px;color:#83908b;margin-top:10px;line-height:1.5}
@media(max-width:800px){.app-shell{padding:0 16px}.topbar{height:75px}.home-grid{grid-template-columns:1fr}.hero-card{min-height:320px;padding:27px}.hero-art{right:18px;bottom:12px;font-size:75px;opacity:.82}.side-stack{grid-template-columns:1fr 1fr}.stage-map{grid-template-columns:repeat(5,1fr)}.stage-node{min-height:62px}.soap-layout{grid-template-columns:1fr}.lab-visual{min-height:270px}.soap-card{padding:22px}.stat-chip{padding:7px 8px;min-width:59px}.lives-chip{min-width:90px}.stat-chip span{font-size:8px}.stat-chip b{font-size:12px}.icon-button{padding:9px}.icon-button span{display:none}}
@media(max-width:520px){.app-shell{padding:0 12px}.topbar{gap:7px}.brand{gap:7px}.brand-icon{height:37px;width:37px}.brand b{font-size:11px}.brand small{font-size:8px}.top-stats{gap:4px}.stat-chip{min-width:auto;padding:6px 7px;border-radius:10px}.lives-chip{min-width:auto}.stat-chip b{font-size:11px}.stage-chip{display:none}.icon-button{font-size:10px}.hero-card{padding:23px 21px;min-height:355px}.hero-card h1{font-size:37px}.hero-card p{font-size:13px;max-width:90%}.hero-art{font-size:70px;right:10px;bottom:5px}.side-stack{grid-template-columns:1fr}.mini-card{padding:17px}.practice-card{align-items:flex-start}.practice-launch{font-size:11px;padding:10px}.map-section{padding:18px 14px}.section-head{align-items:flex-start;flex-direction:column}.stage-map{gap:7px}.stage-node{min-height:56px;border-radius:12px}.options{grid-template-columns:1fr}.question-card{padding:23px 19px}.question-emoji{width:45px;height:45px;right:18px;top:18px;font-size:26px}.question-card h1{padding-right:36px}.question-card .subtitle{font-size:13px}.question-footer{align-items:flex-start;flex-direction:column}.next-button{width:100%;justify-content:center}.soap-heading h1{font-size:24px}.completion-card{padding:26px 18px}.completion-card h1{font-size:31px}footer{font-size:9px;text-align:center}.stat-chip.lives-chip{max-width:78px;overflow:hidden}.top-stats{margin-left:auto}}

const stages = [
 {title:'Heat has a direction',topic:'Heat Transfer',emoji:'🌡️',difficulty:'EASY',color:'#53ad69',type:'choice',question:'A warm object touches a cool object. Which way does heat energy flow?',sub:'Think about the direction heat travels until both objects reach thermal equilibrium.',options:['From the cooler object to the warmer one','From the warmer object to the cooler one','Both ways equally, so nothing changes','Heat only moves through liquids'],answer:1,explain:'Heat flows from the hotter object to the colder one. It continues until both reach the same temperature (thermal equilibrium).'},
 {title:'Three ways heat travels',topic:'Heat Transfer',emoji:'🔥',difficulty:'EASY',color:'#53ad69',type:'choice',question:'A metal spoon warms in hot tea. Which type of heat transfer is this?',sub:'Choose the best example of heat moving through a solid.',options:['Convection — warm fluid rises','Conduction — particles pass energy along','Radiation — waves travel through space','Evaporation — liquid becomes gas'],answer:1,explain:'Conduction transfers heat through direct contact. Convection currents happen in fluids: warm fluid rises and cool fluid sinks. Radiation travels as waves and needs no medium; it can travel at 300,000 km/s.'},
 {title:'Physical or chemical?',topic:'Chemical Reactions',emoji:'🧊',difficulty:'EASY',color:'#53ad69',type:'choice',question:'Ice melts into liquid water. What kind of change is this?',sub:'Ask yourself: did a new substance form?',options:['A chemical change — a new substance formed','A physical change — it is still water','Both physical and chemical at once','Neither; matter disappeared'],answer:1,explain:'Melting is a physical change. The state changes, but the substance is still water. A chemical change makes one or more new substances.'},
 {title:'Reaction clues',topic:'Chemical Reactions',emoji:'🧫',difficulty:'EASY',color:'#53ad69',type:'choice',question:'Which set contains signs that a chemical reaction may have happened?',sub:'A sign is a clue—not always proof by itself!',options:['A solid precipitate, colour change, gas, or light + heat','Only a change in shape','Only melting or freezing','A substance becoming smaller when cut'],answer:0,explain:'Common signs include a precipitate (new solid), colour change, gas bubbles, or light and heat. Silver nitrate can form a white precipitate; zinc in copper sulphate makes the blue colour fade; magnesium + hydrochloric acid bubbles; burning magnesium gives bright light.'},
 {title:'Sugar building blocks',topic:'Nutritional Chemistry',emoji:'🍬',difficulty:'EASY',color:'#53ad69',type:'choice',question:'Which pair are simple sugars (single sugar units)?',sub:'Glucose and fructose are examples of monosaccharides.',options:['Glucose and fructose','Sucrose and maltose','Starch and cellulose','Protein and fat'],answer:0,explain:'Glucose and fructose are monosaccharides (one sugar unit). Sucrose and maltose are disaccharides, built from two simple sugar units.'},
 {title:'Balance the ammonia equation',topic:'Balancing Equations',emoji:'⚖️',difficulty:'MEDIUM',color:'#e9954d',type:'choice',question:'Choose the balanced equation for making ammonia.',sub:'N₂ + H₂ → NH₃. Change coefficients, never the small subscripts.',options:['N₂ + 2H₂ → 2NH₃','N₂ + 3H₂ → 2NH₃','2N₂ + H₂ → 2NH₃','N₂ + H₂ → NH₃'],answer:1,explain:'N₂ + 3H₂ → 2NH₃. There are 2 nitrogen atoms and 6 hydrogen atoms on each side.'},
 {title:'Coefficient or subscript?',topic:'Balancing Equations',emoji:'🔢',difficulty:'MEDIUM',color:'#e9954d',type:'choice',question:'In 2H₂O, how many hydrogen and oxygen atoms are there altogether?',sub:'The coefficient 2 multiplies every atom in the formula H₂O.',options:['2 hydrogen and 1 oxygen','4 hydrogen and 2 oxygen','2 hydrogen and 2 oxygen','4 hydrogen and 1 oxygen'],answer:1,explain:'The coefficient 2 means two water molecules. Each has 2 H and 1 O, so together there are 4 H and 2 O. Subscripts stay part of the substance formula.'},
 {title:'Matter is conserved',topic:'Conservation of Mass',emoji:'⚗️',difficulty:'MEDIUM',color:'#e9954d',type:'choice',question:'222 g of mercury oxide decomposes. If it makes 200 g of mercury, how much oxygen is released?',sub:'In a closed reaction, total mass before = total mass after.',options:['22 g','200 g','222 g','422 g'],answer:0,explain:'222 g = 200 g + oxygen, so oxygen has a mass of 22 g. Atoms are rearranged, not created or destroyed.'},
 {title:'Choose the food test',topic:'Nutritional Chemistry',emoji:'🧪',difficulty:'MEDIUM',color:'#e9954d',type:'choice',question:'Which test is used to detect starch?',sub:'Match the food nutrient with its indicator solution.',options:['Benedict’s solution','Iodine solution','Sudan stain','Biuret solution'],answer:1,explain:'Iodine tests for starch and turns blue-black when starch is present. Benedict’s tests for reducing sugars; Sudan tests for fats; Biuret tests for proteins.'},
 {title:'What is in our food?',topic:'Nutritional Chemistry',emoji:'🥚',difficulty:'MEDIUM',color:'#e9954d',type:'choice',question:'Which elements are found in fats, carbohydrates, and proteins—and which element is an extra clue for proteins?',sub:'Think of the elements in the three main food groups.',options:['All contain C, H, O; proteins also contain N','All contain C, H, N; proteins also contain O','Only proteins contain carbon','Fats contain nitrogen but carbohydrates do not'],answer:0,explain:'Carbohydrates and fats contain carbon, hydrogen and oxygen. Proteins also contain these elements and usually nitrogen (N).'},
