  panel=`<div class="measure-display" id="measureDisplay">${value} mL</div><div class="measure-sub">TARGET · ${target} mL ${unit.toUpperCase()}</div><input class="range" id="measureRange" aria-label="Measure ${unit}" type="range" min="0" max="${target+30}" step="5" value="${value}"><div class="button-row"><button class="secondary" id="measureMinus">− 5 mL</button><button class="secondary" id="measurePlus">+ 5 mL</button></div><div class="button-row"><button class="primary" id="confirmMeasure">Add to beaker →</button></div><div class="inline-help" id="soapHint">Use the slider or buttons. Accuracy matters!</div>`;
 }else if(s?.kind==='heat'){
  panel=`<div class="measure-display" id="tempDisplay">${soap.temp}°C</div><div class="measure-sub">SAFE SIMULATION ZONE · 40°C–50°C</div><input class="range" id="tempRange" aria-label="Temperature control" type="range" min="20" max="70" step="1" value="${soap.temp}"><div class="thermo-track"><span>20°</span><span class="green-band">40° — 50° GREEN ZONE</span><span>70°</span></div><div class="button-row"><button class="primary" id="confirmHeat">Set temperature →</button></div><div class="inline-help" id="soapHint">Tap the burner control, then hold the thermometer in the green zone.</div>`;
 }else if(s?.kind==='stir'){
  panel=`<div class="stir-wrap"><div class="stir-instruction">Stir clockwise ↻</div><div class="stir-pad" id="stirPad"><span class="stir-arrow">↻</span><span class="stir-center">🧪</span></div><div class="stir-progress"><span id="stirBar"></span></div><div class="stir-caption" id="stirCaption">0% · 0 of 3 clockwise rotations</div><div class="stir-error" id="stirError"></div></div><div class="inline-help">Drag a continuous circle clockwise. Counter-clockwise movement never adds progress.</div>`;
 }else if(s?.kind==='pour'){
  panel=`<div class="stage-feedback">✨ The mixture is thicker and its colour has changed. That is a clue that new substances are forming.</div><div class="button-row"><button class="primary" id="pourButton">Pour into mold →</button></div>`;
 }else if(s?.kind==='wait'){
  panel=`<div class="mold-card"><div>🧼</div><b>SOAP IS SETTING…</b><small>Patience is part of the process!</small></div><div class="button-row"><button class="primary" id="waitButton">Wait for it to set →</button></div>`;
 }else if(s?.kind==='cut'){
  panel=`<button class="soap-cut" id="cutSoap" aria-label="Cut the soap">🧼<span>✂️</span></button><div class="inline-help">Tap the soap bar to cut it!</div>`;
 }
 const stepMark=soap.step===0?0:soap.step===1?20:soap.step===2?40:soap.step===3?55:soap.step===4?72:soap.step===5?84:94;
 app.innerHTML=`<section class="soap-screen"><button class="home-link" id="soapHome">← ${isPractice?'Back to lab menu':'Stage map'}</button>${isPractice?'<div class="practice-banner">🧼 PRACTICE LAB · Explore the soap-making simulation at your own pace. Progress is not affected.</div>':''}<article class="soap-card"><div class="soap-heading"><div><span class="difficulty" style="color:${stages[19].color}"><span></span>${isPractice?'PRACTICE LAB':'HELL IN A CELL · FINAL BOSS'}</span><h1>${full?'SOAP FORMED!':`Stage 20 · ${s.name}`}</h1><p>${full?'A new substance has formed! Read the science below.':s.prompt}</p></div><span class="pill-tag">${full?'FINISHED':`STEP ${stepNumber} / 7`}</span></div>${!full?`<div class="stage-progress"><span style="width:${stepMark}%;background:#df6965"></span></div>`:''}<div class="soap-layout"><div class="lab-visual"><span class="thermometer" id="thermometer">🌡️</span><div class="beaker-wrap"><div class="beaker"><div class="liquid" id="liquid" style="height:${visualLevel}%;background:${soap.step>=4?'#a9cd78':soap.step>=2?'#f0d47a':'#e9bd5c'}"></div><span class="beaker-label">${soap.step>=4?'THICKENING MIX':soap.step>=2?'WARM MIX':'MIXING BEAKER'}</span></div><div class="beaker-caption">${soap.step>=4?'🫧 Saponification in progress':'🧪 Your experiment'}</div></div></div><div class="soap-panel"><span class="step-count">${full?'THE SCIENCE':`LAB STEP ${stepNumber}`}</span><h2 class="step-title">${full?'What happened?':s.name}</h2><p class="step-copy">${full?'Saponification is the reaction of oil (fat) with an alkali to form soap and glycerol. The new products have different properties, so this is a chemical change.':s.prompt}</p>${full?`<div class="stage-feedback">✅ <b>SOAP FORMED!</b> Chemical change — new substance + consistency change!<br><br><span class="safety-note">Safety reminder: caustic soda is dangerous. Real soap-making with caustic soda must be done by a teacher using proper protective equipment. This is only a game simulation.</span></div><div class="button-row"><button class="primary" id="soapFinish">${isPractice?'Back to menu':'Claim Soap Master title →'}</button></div>`:panel}</div></div>${!full&&soap.step===1?'<p class="safety-note" style="margin:20px 0 0">⚠️ Caustic soda is dangerous — teacher only in real life! This screen is a safe, virtual simulation. Never handle it yourself.</p>':''}</article></section>`;
 document.getElementById('soapHome').onclick=()=>isPractice?home():home();
 const liquid=document.getElementById('liquid');if(liquid&&soap.step>=2)liquid.style.height=visualLevel+'%';
 if(s?.kind==='oil'||s?.kind==='soda')bindMeasure(s.kind);
 if(s?.kind==='heat')bindHeat();
 if(s?.kind==='stir')bindSoapStir();
 if(s?.kind==='pour')document.getElementById('pourButton').onclick=()=>advanceSoap();
 if(s?.kind==='wait')document.getElementById('waitButton').onclick=()=>{const btn=document.getElementById('waitButton');btn.disabled=true;btn.textContent='Setting…';setTimeout(advanceSoap,1300)};
 if(s?.kind==='cut')document.getElementById('cutSoap').onclick=()=>{confetti();soap.step=7;renderSoap()};
 if(full)document.getElementById('soapFinish').onclick=()=>{if(isPractice){home();toast('Practice complete — great stirring!')}else finishStage()};
}
function bindMeasure(kind){const range=document.getElementById('measureRange'),display=document.getElementById('measureDisplay');const property=kind==='oil'?'oil':'soda';const target=kind==='oil'?100:30;const update=v=>{soap[property]=Number(v);display.textContent=`${v} mL`;const liquid=document.getElementById('liquid');liquid.style.height=(kind==='oil'?v/100*30:30+v/30*20)+'%'};range.oninput=e=>update(e.target.value);document.getElementById('measureMinus').onclick=()=>{range.value=Math.max(0,+range.value-5);update(range.value)};document.getElementById('measurePlus').onclick=()=>{range.value=Math.min(+range.max,+range.value+5);update(range.value)};document.getElementById('confirmMeasure').onclick=()=>{const hint=document.getElementById('soapHint');if(soap[property]!==target){hint.textContent=soap[property]>target?`Too much ${kind==='oil'?'oil':'caustic soda'} — set exactly ${target} mL and try again.`:`Add exactly ${target} mL. Adjust the amount before continuing.`;hint.style.color='#c34a41';return}if(kind==='oil'){soap.step=1;renderSoap()}else{soap.step=2;soap.temp=25;renderSoap()}}}
function bindHeat(){const range=document.getElementById('tempRange'),display=document.getElementById('tempDisplay'),therm=document.getElementById('thermometer');range.oninput=e=>{soap.temp=+e.target.value;display.textContent=soap.temp+'°C';if(therm)therm.style.transform=`translateY(${(soap.temp-25)*-.7}px)`};document.getElementById('confirmHeat').onclick=()=>{const hint=document.getElementById('soapHint');if(soap.temp>50){hint.textContent='Too hot! The mixture has overheated. Cool it and reset this heating step.';hint.style.color='#bf463e';if(!soap.practice){lives--;setStats(true);if(lives<=0){setTimeout(restartStage,900);return}}soap.temp=25;range.value=25;display.textContent='25°C';return}if(soap.temp<40){hint.textContent='Not warm enough yet. Raise the temperature into the 40°C–50°C green zone.';hint.style.color='#b27a2f';return}soap.step=3;renderSoap()}}
function bindSoapStir(){bindStir(document.getElementById('stirPad'),1080,pct=>{document.getElementById('stirBar').style.width=pct+'%';document.getElementById('stirCaption').textContent=`${pct}% · ${(pct/100*3).toFixed(1)} of 3 clockwise rotations`;},()=>{soap.stirDone=true;soap.step=4;renderSoap()})}
function bindStir(pad,fullDegrees,onProgress,onDone){let last=null,total=0,active=false,done=false;const error=document.getElementById('stirError');const angle=e=>{const r=pad.getBoundingClientRect();return Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2))};pad.addEventListener('pointerdown',e=>{active=true;pad.classList.add('dragging');pad.setPointerCapture(e.pointerId);last=angle(e);if(error)error.textContent=''});pad.addEventListener('pointermove',e=>{if(!active||done)return;const now=angle(e);let diff=now-last;while(diff>Math.PI)diff-=Math.PI*2;while(diff< -Math.PI)diff+=Math.PI*2;last=now;if(diff<-.025){if(error){error.textContent='WRONG DIRECTION! Clockwise only!';setTimeout(()=>{if(error)error.textContent=''},1200)}return}if(diff>.012){total+=Math.min(diff,.35);const pct=Math.min(100,Math.floor(total/(fullDegrees*Math.PI/180)*100));onProgress(pct);if(pct>=100&&!done){done=true;active=false;pad.classList.remove('dragging');onDone()}}});const release=()=>{active=false;last=null;pad.classList.remove('dragging')};pad.addEventListener('pointerup',release);pad.addEventListener('pointercancel',release);}
function advanceSoap(){soap.step++;renderSoap()}
function start(){document.getElementById('homeButton').onclick=home;renderHome();setStats(false)}
start();

